inline constexpr int PRIMO_VARCO = 64;   // cella = PRIMO_VARCO + indice del varco
inline constexpr int PRIMA_CELLA_SOLIDA = 11;
inline constexpr int DISTANZA_MIN_SPAWN = 3;
inline constexpr int DISTANZA_MIN_SPAWN_USCITA = 6;
inline constexpr int LATO_MAX = 128;          // tile per lato di un'area
inline constexpr int SPAWN_PER_AREA = 8;
inline constexpr int VARCHI_MAX = 6;

enum class AreaId : uint8_t
{
    PIAZZA_GRANDE,
    VIA_XX_SETTEMBRE,
    DUOMO_DUCALE,
    MONTE_INGINO,
    BASILICA,
    BOTTACCIONE,
    SAN_MARTINO,
    LARGO_BARGELLO,
    VIA_DEI_CONSOLI,
    BASILICA_INTERNO,
    CONDOTTO,
    GOLA_ARCO,
    GOLA_MIASMI,
    GOLA_STRISCIA,
    PIAZZA_QUARANTA_MARTIRI,
    SAN_PIETRO,
    SANT_AGOSTINO,
    SANT_ANDREA,
    TEATRO_ROMANO,
    TAVERNA_INTERNO,
    SPEZIERIA_INTERNO,
    BOTTEGA_CONTI_INTERNO,
    CARRADORE_INTERNO,
    CASA_MEDICO_INTERNO,
    SALA_CONSOLI,
};

inline constexpr int AREE_CONTEGGIO = 25;
inline constexpr int ANELLO_CONTEGGIO = 9;
inline constexpr AreaId ANELLO[ANELLO_CONTEGGIO] = {
    AreaId::PIAZZA_GRANDE, AreaId::VIA_XX_SETTEMBRE, AreaId::DUOMO_DUCALE, AreaId::MONTE_INGINO, AreaId::BASILICA, AreaId::BOTTACCIONE, AreaId::SAN_MARTINO, AreaId::LARGO_BARGELLO, AreaId::VIA_DEI_CONSOLI,
};

inline constexpr int DUNGEON = -1;   // destinazione di un ingresso che in F2 non porta altrove

struct Punto
{
    uint8_t x;
    uint8_t y;
};

struct Varco
{
    int8_t destinazione;              // AreaId, oppure DUNGEON
    uint8_t spawn;                    // spawn d'arrivo nell'area di destinazione
    testi::TestoId etichetta;         // per un DUNGEON: il nome mostrato all'ingresso
};

struct Area
{
    const uint8_t* griglia;           // larghezza * altezza celle
    const uint8_t* mappa;             // larghezza * altezza tile del fondale
    uint8_t larghezza;
    uint8_t altezza;
    const uint16_t* fondale;          // celle della mappa BG (vedi lati_fondale in genera_mondo.py)
    uint8_t larghezza_fondale;
    uint8_t altezza_fondale;
    bool fondale_grande;              // big map (oltre 64 tile): celle riga per riga
    const bn::tile* tile;             // i tile 8x8 dell'area (il primo e' il vuoto)
    uint16_t tile_conteggio;
    int16_t quota_da;                 // metri sopra Piazza Quaranta Martiri
    int16_t quota_a;                  // diversa da quota_da solo per le strade in salita
    testi::TestoId etichetta;
    uint8_t varchi;
    Varco varco[VARCHI_MAX];
    Punto spawn[SPAWN_PER_AREA];
    bool interno;                     // un interno ('interno' nel .area): fuori dalla nebbia della mappa
    bool cupa;                        // le stanze della gola: la palette cupa (PALETTE_FONDALI_CUPA)
};

